import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"ChatGPT Chrome Extension","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/codex/codex-chrome.md","filePath":"products/ai-coding/codex/codex-chrome.md","lastUpdated":1787046041000}'),s={name:"products/ai-coding/codex/codex-chrome.md"};function n(i,t,l,h,d,c){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="chatgpt-chrome-extension" tabindex="-1">ChatGPT Chrome Extension <a class="header-anchor" href="#chatgpt-chrome-extension" aria-label="Permalink to &quot;ChatGPT Chrome Extension&quot;">​</a></h1><blockquote><p>A <strong>tutorial</strong> — let ChatGPT drive <strong>your</strong> Chrome profile so it can act on sites you are already signed into. Treat every page as untrusted context. Review the site before you allow the agent to continue.</p><p>Official landing: <a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/chrome-extension</a>. Docs: <a href="https://learn.chatgpt.com/docs/chrome-extension" target="_blank" rel="noreferrer">Chrome extension</a>.</p></blockquote><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Requirement</th></tr></thead><tbody><tr><td>Browser</td><td><strong>Google Chrome</strong> only. Other Chromium browsers are not supported</td></tr><tr><td>Desktop</td><td><a href="https://learn.chatgpt.com/docs/app" target="_blank" rel="noreferrer">ChatGPT desktop app</a> with Work or Codex</td></tr><tr><td>Store item</td><td><a href="https://chromewebstore.google.com/detail/chatgpt/hehggadaopoacecdllhhajmbjkdcmajg" target="_blank" rel="noreferrer">ChatGPT Chrome extension</a></td></tr></tbody></table><p><strong>Learning objectives</strong>: install the plugin + extension; start a side chat on the current tab; invoke <code>@Chrome</code> from Work or Codex; set allow / block lists; tell Chrome apart from the built-in browser.</p><p><strong>Non-goals</strong>: Atlas (retired 2026-08-09); Cloud browser sign-in (it cannot use your cookies); a second desktop Codex tutorial (<a href="./codex-ai.html">product line</a>).</p><h2 id="three-browsers-one-job-each" tabindex="-1">Three browsers, one job each <a class="header-anchor" href="#three-browsers-one-job-each" aria-label="Permalink to &quot;Three browsers, one job each&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it is</th><th>Use when</th></tr></thead><tbody><tr><td><strong>Chrome extension</strong></td><td>Controls <strong>your</strong> Chrome, including signed-in tabs</td><td>LinkedIn, Salesforce, Gmail, internal tools</td></tr><tr><td><strong>Built-in browser</strong> (<code>@Browser</code>)</td><td>A separate ChatGPT profile inside the desktop app</td><td>Localhost preview, research, stay out of your Chrome</td></tr><tr><td><strong>Work cloud browser</strong></td><td>Hosted, signed-out browser on the web</td><td>Public pages; no local tabs or passwords</td></tr></tbody></table><p>ChatGPT can switch tools mid-task: a <strong>plugin</strong> when a dedicated integration exists, <strong>Chrome</strong> when it needs your logged-in session, <strong>built-in browser</strong> for localhost.</p><p>Built-in browser docs: <a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a>. Atlas is gone; see the <a href="./">Learning Map</a>.</p><h2 id="step-1-—-install" tabindex="-1">Step 1 — Install <a class="header-anchor" href="#step-1-—-install" aria-label="Permalink to &quot;Step 1 — Install&quot;">​</a></h2><p>In the desktop app, open <strong>Plugins</strong> and install <strong>Chrome</strong>. Follow the flow:</p><ol><li>Install the <a href="https://chromewebstore.google.com/detail/chatgpt/hehggadaopoacecdllhhajmbjkdcmajg" target="_blank" rel="noreferrer">Chrome extension</a>.</li><li>Approve Chrome’s permission prompts.</li><li>Open Chrome and confirm the ChatGPT side chat loads.</li></ol><p>Use the <strong>same Chrome profile</strong> that has the extension. Install it again if you switch profiles.</p><h2 id="step-2-—-chat-beside-the-page" tabindex="-1">Step 2 — Chat beside the page <a class="header-anchor" href="#step-2-—-chat-beside-the-page" aria-label="Permalink to &quot;Step 2 — Chat beside the page&quot;">​</a></h2><ol><li>Open the page.</li><li>Click ChatGPT in the toolbar or <strong>Extensions</strong>. On macOS: <code>Cmd+Shift+.</code>.</li><li>Ask about the page or give a task.</li></ol><p>The panel stays with that tab. Chats started in Chrome appear in the ChatGPT app, and recent app chats can open in Chrome.</p><p>Mention an open tab, or highlight text and bring the selection into the chat. Right-click → <strong>Ask ChatGPT</strong> to start from the page.</p><p>On YouTube, ChatGPT can use timestamped captions when they exist. Still treat the transcript as untrusted.</p><h2 id="step-3-—-start-a-chrome-task-from-chatgpt" tabindex="-1">Step 3 — Start a Chrome task from ChatGPT <a class="header-anchor" href="#step-3-—-start-a-chrome-task-from-chatgpt" aria-label="Permalink to &quot;Step 3 — Start a Chrome task from ChatGPT&quot;">​</a></h2><p>Start a <strong>Work</strong> or <strong>Codex</strong> chat. ChatGPT uses Chrome when the task needs a signed-in site. You can invoke it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Chrome open Salesforce and update the account from these call notes.</span></span></code></pre></div><p>If Chrome is closed, ChatGPT can open it. Tasks run in Chrome <strong>tab groups</strong>.</p><h2 id="control-website-access" tabindex="-1">Control website access <a class="header-anchor" href="#control-website-access" aria-label="Permalink to &quot;Control website access&quot;">​</a></h2><p>By default ChatGPT asks per <strong>host</strong> (<code>example.com</code>) before it interacts.</p><table tabindex="0"><thead><tr><th>Choice</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Allow once</strong></td><td>This request only</td></tr><tr><td><strong>Allow for this site</strong></td><td>This host without asking again</td></tr><tr><td><strong>Allow for all sites</strong></td><td>No per-site prompt. Elevated risk</td></tr><tr><td><strong>Decline</strong></td><td>Do not use the site</td></tr></tbody></table><p>Manage lists in the desktop app: <strong>Settings → Computer Use → Google Chrome → Manage</strong>. Allowlist = do not ask. Blocklist = do not use. Removing a domain from either list returns you to “ask again.”</p><p><strong>Allow for all sites</strong> means ChatGPT will not ask before using websites. Only choose it if you trust the agent with any tab in that Chrome profile.</p><p><strong>Browser history</strong> is a separate, elevated-risk prompt. History can include internal URLs, search terms, and activity on signed-in devices. Access is scoped to the request. There is <strong>no</strong> always-allow for history.</p><h2 id="data-and-permissions" tabindex="-1">Data and permissions <a class="header-anchor" href="#data-and-permissions" aria-label="Permalink to &quot;Data and permissions&quot;">​</a></h2><p>Chrome may ask for debugger access, all-site data, history on signed-in devices, notifications, bookmarks, downloads, native messaging, and tab groups. Those capabilities make browser workflows possible. ChatGPT still uses its own confirmations, allowlists, and blocklists.</p><p>Memories follow your Memories setting.</p><p>OpenAI does <strong>not</strong> store a separate complete log of Chrome actions. It stores browser activity only when that activity becomes chat context (text, screenshots, tool calls, summaries). Your ChatGPT data controls apply. Do not send secrets through a browser task unless you are present for every prompt.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If ChatGPT cannot connect to Chrome:</p><ol><li>Confirm the host is not on the blocklist.</li><li>Update every ChatGPT / Codex desktop app you still have installed.</li><li>Close the side panel, restart Chrome, reopen the extension. If you see a missing native host, remove and re-add the Chrome plugin.</li><li>In the app, switch to <strong>Work</strong> or <strong>Codex</strong>. Confirm the Chrome plugin is on.</li><li>Use the Chrome profile that has the extension.</li><li>Start a new Work or Codex chat.</li><li>Restart the desktop app; last resort, uninstall the extension and re-run setup.</li><li>Side chat works but Chrome tasks fail: <code>/feedback</code> and include the chat ID.</li></ol><p>File uploads from disk: Chrome → extension <strong>Details → Allow access to file URLs</strong>, then retry the task.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pitfall</th><th>What happens</th><th>Do this instead</th></tr></thead><tbody><tr><td>Using Edge / Arc / Brave</td><td>Extension is not supported</td><td>Google Chrome</td></tr><tr><td>Allowing all sites on a personal profile</td><td>Agent can touch bank / mail / admin consoles</td><td>Per-site allow; keep a dedicated profile</td></tr><tr><td>Always-allowing history</td><td>Not offered — for good reason</td><td>Approve history only for that request</td></tr><tr><td>Expecting the cloud browser to see Gmail</td><td>Cloud browser is signed out</td><td>Use this extension, or a plugin</td></tr><tr><td>Confusing <code>@Chrome</code> with <code>@Browser</code></td><td>Wrong profile, missing localhost or cookies</td><td><code>@Browser</code> = built-in; <code>@Chrome</code> = your Chrome</td></tr></tbody></table><h2 id="real-world-use" tabindex="-1">Real-world use <a class="header-anchor" href="#real-world-use" aria-label="Permalink to &quot;Real-world use&quot;">​</a></h2><p>A frontend bug only reproduces in the staging admin you are already signed into. Start a Codex chat, <code>@Chrome</code> that tab, ask it to capture the failing flow, then fix the component locally. Keep payroll and password-manager tabs out of that Chrome profile.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Built-in browser and comments → <a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></li><li>Desktop Computer Use (apps, not just Chrome) → <a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></li><li>Hosted public pages → <a href="./sites.html">Sites</a></li></ol><h2 id="official-sources" tabindex="-1">Official sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official sources&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/chrome-extension" target="_blank" rel="noreferrer">Chrome extension (landing)</a></li><li><a href="https://learn.chatgpt.com/docs/chrome-extension" target="_blank" rel="noreferrer">Chrome extension (docs)</a></li><li><a href="https://chromewebstore.google.com/detail/chatgpt/hehggadaopoacecdllhhajmbjkdcmajg" target="_blank" rel="noreferrer">Chrome Web Store</a></li><li><a href="https://help.openai.com/en/articles/20001277-using-the-built-in-browser-in-the-chatgpt-desktop-app" target="_blank" rel="noreferrer">Built-in browser (help)</a></li><li><a href="https://learn.chatgpt.com/docs/browser" target="_blank" rel="noreferrer">Browser</a></li><li><a href="https://learn.chatgpt.com/docs/computer-use" target="_blank" rel="noreferrer">Computer Use</a></li></ul>',45)])])}const f=e(s,[["render",n]]);export{b as __pageData,f as default};
